select t.contract_id,t.contract_id contractId,t.fee_name,t.fee_name feeName,t.plan_name,t.plan_name
planName,t.plan_id,t.plan_id planId,t.remark,t.status_cd,t.status_cd statusCd,t.store_id,t.store_id
storeId,t.fee_id,t.fee_id feeId,
t.plan_seq planSeq, t.plan_time planTime, t.plan_amount planAmount, t.ratio ratio,
case when ifnull(t.pay_state,'0') = '0' and t.plan_time < now() then '2' else ifnull(t.pay_state,'0') end payState, t.pay_time payTime, t.trigger_desc triggerDesc, t.fee_type feeType,
t.create_time createTime
from contract_collection_plan t
where 1 =1

    and t.contract_id= #{contractId}


    and t.contract_id in

        #{item}



    and t.fee_name= #{feeName}


    and t.plan_name= #{planName}


    and t.plan_id= #{planId}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.store_id= #{storeId}


    and t.fee_id= #{feeId}


    and ifnull(t.pay_state,'0') = #{payState}


    and ifnull(t.pay_state,'0') in

        #{item}



    and t.plan_time >= #{planTimeBegin}


    and t.plan_time <= #{planTimeEnd}

order by t.plan_seq asc, t.create_time asc

    limit #{page}, #{row}

