    , t.plan_seq= #{planSeq}


    , t.plan_time= #{planTime}


    , t.plan_amount= #{planAmount}


    , t.ratio= #{ratio}


    , t.pay_state= #{payState}


    , t.pay_time= null


    , t.pay_time= #{payTime}


    , t.pay_time= null


