mapper.select:
select count(1) count
from contract_collection_plan t
where 1 =1

    and t.contract_id= #{contractId}


    and t.contract_id in

        #{item}



    and t.fee_name= #{feeName}


    and t.plan_name= #{planName}


    and t.plan_id= #{planId}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.store_id= #{storeId}


    and t.fee_id= #{feeId}


    and ifnull(t.pay_state,'0') = #{payState}

select p.contract_id contractId, ifnull(sum(case when p.pay_state = '1' then p.plan_amount else 0 end), 0) paidAmount, ifnull(sum(case when ifnull(p.pay_state, '0') <> '1' then p.plan_amount else 0 end), 0) unpaidAmount, ifnull(sum(case when p.pay_state = '2' or (ifnull(p.pay_state,'0') = '0' and p.plan_time < now()) then 1 else 0 end), 0) overdueCount, ifnull(sum(case when p.pay_state = '1' then 1 else 0 end), 0) paidCount, count(p.plan_id) planCount, ifnull(sum(p.plan_amount), 0) totalAmount, min(case when ifnull(p.pay_state, '0') <> '1' then p.plan_time end) nextPlanTime from contract_collection_plan p where p.status_cd = '0'
and p.contract_id = #{contractId}
and p.contract_id in
#{item}
and p.store_id = #{storeId}
group by p.contract_id
